const b = $json.body ?? $json;

const trim = (v) => (typeof v === 'string' ? v.trim().replace(/\s+/g, ' ') : '');

const digitMap = {
  '۰':'0','۱':'1','۲':'2','۳':'3','۴':'4','۵':'5','۶':'6','۷':'7','۸':'8','۹':'9',
  '٠':'0','١':'1','٢':'2','٣':'3','٤':'4','٥':'5','٦':'6','٧':'7','٨':'8','٩':'9',
};
const normalizePhone = (v) => trim(v).replace(/[۰-۹٠-٩]/g, (d) => digitMap[d] ?? d);

const name = trim(b.name);
const lastName = trim(b.lastName);
const gender = trim(b.gender);
const phone = normalizePhone(b.phone);
const email = trim(b.email);
const ageCategory = trim(b.ageCategory);
const message = trim(b.message);
const rawSourcePage = trim(b.sourcePage);
const workshopTitle = trim(b.workshopTitle);

const requiredFields = { name, lastName, gender, phone, ageCategory };
const missingFields = Object.entries(requiredFields)
  .filter(([, v]) => !v)
  .map(([k]) => k);

return {
  json: {
    name, lastName, gender, phone, email, ageCategory, message,
    rawSourcePage, workshopTitle, missingFields,
  },
};

const pageMap = {
  'math': 'math', 'ریاضی': 'math',
  'english': 'english', 'انگلیسی': 'english',
  'ai': 'ai', 'هوش مصنوعی': 'ai',
  'workshops': 'workshop', 'workshop': 'workshop', 'کارگاه': 'workshop', 'کارگاه‌ها': 'workshop',
  'home page': 'homepage', 'homepage': 'homepage', 'home': 'homepage',
};

const raw = $json.rawSourcePage || '';
const key = raw.trim().toLowerCase();
const matched = pageMap[key] ?? null;

// Anything we don't recognize goes to a dedicated 'unknown' bucket — it must
// NOT silently fall into Homepage or any other real page's sheet.
const canonicalPage = matched ?? 'unknown';

// If a workshop title was actually submitted, use it verbatim — regardless
// of which page it came from. Only fall back to the generic-interest label
// when there's no title AND this is recognizably the workshop page (the
// dedicated 'I'm interested in workshops' form has no title field at all).
let workshopName = '';
if ($json.workshopTitle) {
  workshopName = $json.workshopTitle;
} else if (canonicalPage === 'workshop') {
  workshopName = 'علاقه‌مندی عمومی به کارگاه‌ها (بدون انتخاب کارگاه مشخص)';
}

return {
  json: {
    ...$json,
    canonicalPage,
    isUnknownSource: matched === null,
    workshopName,
  },
};

