const src = $('Detect Source & Workshop').item.json;

// Fixed fallback — used whenever the AI call fails or returns something
// that isn't valid { lead_score: 1-5 int, score_reason: non-empty string }.
let score = 3;
let reason = 'امتیازدهی خودکار انجام نشد؛ نیاز به بررسی دستی';

try {
  if ($json.error) throw new Error('AI request failed');
  const raw = $json.choices?.[0]?.message?.content ?? '';
  const cleaned = raw.trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```\s*$/i, '');
  const parsed = JSON.parse(cleaned);
  const s = Number(parsed.lead_score);
  const r = parsed.score_reason;
  if (Number.isInteger(s) && s >= 1 && s <= 5 && typeof r === 'string' && r.trim()) {
    score = s;
    reason = r.trim();
  }
} catch (e) {
  // keep the fixed fallback score/reason set above — the submission is still saved
}

// Defensive redaction — even if the model ignored the system prompt, never
// let the phone number or email leak into the human-readable reason text.
const redact = (text, value) => {
  if (!value) return text;
  const escaped = String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return text.replace(new RegExp(escaped, 'gi'), '[اطلاعات تماس حذف شد]');
};
reason = redact(reason, src.phone);
reason = redact(reason, src.email);

if (src.isUnknownSource) {
  reason = `⚠️ صفحه منبع نامشخص بود ("${src.rawSourcePage}") — برای بررسی دستی به مسیر Error/Review فرستاده شد. ${reason}`;
}

return {
  json: {
    ...src,
    leadScore: score,
    scoreReason: reason,
  },
};

const errorMsg = $json.error?.message || (typeof $json.error === 'string' ? $json.error : null) || 'خطای نامشخص در Google Sheets';

const lines = [
  'ثبت یک Submission در Google Sheets پس از چند تلاش ناموفق بود. لطفاً اطلاعات زیر را به‌صورت دستی در تب مربوطه وارد کنید تا از دست نرود:',
  '',
  `صفحه: ${$json.canonicalPage ?? 'نامشخص'}${$json.workshopName ? ' | کارگاه: ' + $json.workshopName : ''}`,
  `نام: ${$json.name ?? ''}`,
  `نام خانوادگی: ${$json.lastName ?? ''}`,
  `جنسیت: ${$json.gender ?? ''}`,
  `شماره تماس: ${$json.phone ?? ''}`,
  `ایمیل: ${$json.email ?? ''}`,
  `رده سنی: ${$json.ageCategory ?? ''}`,
  `پیام: ${$json.message ?? ''}`,
  `امتیاز مشتری بالقوه: ${$json.leadScore ?? ''}`,
  `دلیل امتیاز: ${$json.scoreReason ?? ''}`,
  '',
  `پیام خطا: ${errorMsg}`,
  `زمان: ${new Date().toISOString()}`,
];

return {
  json: {
    subject: 'خطا در ثبت یک Submission در Google Sheets — نیاز به بررسی دستی',
    text: lines.join('\n'),
  },
};
